14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    while let Some(arg) = raw_args.next(&mut cursor) {
46	        let current_state = next_state;
47	        next_state = ParseState::ValueDone;
48	        debug!(
49	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
50	            arg.to_value_os(),
51	        );
52	        if cursor == target_cursor {
53	            return complete_arg(
54	                &arg,
55	                current_cmd,
56	                current_dir,
57	                pos_index,
58	                is_escaped,
59	                current_state,
60	                &used_args,
61	            );
62	        }
63	
64	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
65	            if let Ok(value) = arg.to_value() {
66	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
67	                    current_cmd = next_cmd;
68	                    pos_index = 1;
69	                    used_args.clear();
70	                    continue;
71	                }
72	            }
73	        }
74	
75	        if is_escaped {
76	            (next_state, pos_index) =
77	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
78	        } else if arg.is_escape() {
79	            is_escaped = true;
80	        } else if opt_allows_hyphen(&current_state, &arg) {
81	            match current_state {
82	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
83	                _ => unreachable!("else branch is only reachable in Opt state"),
84	            }
85	        } else if let Some((flag, value)) = arg.to_long() {
86	            if let Ok(flag) = flag {
87	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
88	
89	                if let Some(opt) = opt {
90	                    record_used_arg(&mut used_args, opt.get_id());
91	                    if opt.get_num_args().expect("built").takes_values() {
92	                        // An attached value (`--opt=value`) counts toward the
93	                        // option's values just like a space-separated one, so
94	                        // that completing after `--opt=value` sees the same
95	                        // state as completing after `--opt value`.
96	                        // An empty attached value (`--opt=`) types no value
97	                        // yet, so the option stays pending.
98	                        let count = value
99	                            .filter(|v| !v.is_empty())
100	                            .map(|v| attached_value_count(opt, v))
101	                            .unwrap_or(0);
102	                        next_state = parse_opt_value(opt, count);
103	                    };
104	                } else if pos_allows_hyphen(current_cmd, pos_index) {
105	                    (next_state, pos_index) =
106	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
107	                }
108	            }
109	        } else if let Some(short) = arg.to_short() {
110	            let (_, matched_opts, takes_value_opt, mut short) =
111	                parse_shortflags(current_cmd, short);
112	            for opt in &matched_opts {
113	                record_used_arg(&mut used_args, opt.get_id());
114	            }
115	            if let Some(opt) = takes_value_opt {
116	                // An attached value (`-ovalue`, `-o=value`) counts toward the
117	                // option's values just like a space-separated one. An empty
118	                // attached value (`-o=`) types no value yet, so the option
119	                // stays pending instead of being treated as satisfied.
120	                let count = short
121	                    .next_value_os()
122	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
123	                    .filter(|v| !v.is_empty())
124	                    .map(|v| attached_value_count(opt, v))
125	                    .unwrap_or(0);
126	                next_state = parse_opt_value(opt, count);
127	            } else if pos_allows_hyphen(current_cmd, pos_index) {
128	                (next_state, pos_index) =
129	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
130	            }
131	        } else {
132	            match current_state {
133	                ParseState::ValueDone | ParseState::Pos(..) => {
134	                    (next_state, pos_index) =
135	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
136	                }
137	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
138	            }
139	        }
140	    }
141	
142	    Err(std::io::Error::other("no completion generated"))
143	}
144	
145	#[derive(Debug, PartialEq, Eq, Clone)]
146	enum ParseState<'a> {
147	    /// Parsing a value done, there is no state to record.
148	    ValueDone,
149	
150	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
151	    Pos((usize, usize)),
152	
153	    /// Parsing a optional flag argument
154	    Opt((&'a clap::Arg, usize)),
155	}
156	
157	fn complete_arg(
158	    arg: &clap_lex::ParsedArg<'_>,
159	    cmd: &clap::Command,
160	    current_dir: Option<&std::path::Path>,
161	    pos_index: usize,
162	    is_escaped: bool,
163	    state: ParseState<'_>,
164	    used_args: &[clap::Id],
165	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
166	    debug!(
167	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
168	        arg,
169	        cmd.get_name(),
170	        current_dir,
171	        pos_index,
172	        state
173	    );
174	    let mut completions = Vec::<CompletionCandidate>::new();
175	
176	    match state {
177	        ParseState::ValueDone => {
178	            if !is_escaped {
179	                if let Ok(value) = arg.to_value() {
180	                    completions.extend(complete_subcommand(value, cmd));
181	                }
182	            }
183	
184	            if let Some(positional) = cmd
185	                .get_positionals()
186	                .find(|p| p.get_index() == Some(pos_index))
187	            {
188	                completions.extend(complete_arg_value(
189	                    arg.to_value(),
190	                    positional,
191	                    current_dir,
192	                    0,
193	                ));
194	            }
195	            if !is_escaped {
196	                completions.extend(complete_option(arg, cmd, current_dir));
197	            }
198	        }
199	        ParseState::Pos((_, num_arg)) => {
200	            if let Some(positional) = cmd
201	                .get_positionals()
202	                .find(|p| p.get_index() == Some(pos_index))
203	            {
204	                completions.extend(complete_arg_value(
205	                    arg.to_value(),
206	                    positional,
207	                    current_dir,
208	                    num_arg.saturating_sub(1),
209	                ));
210	                if !is_escaped
211	                    && positional
212	                        .get_num_args()
213	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
214	                {
215	                    completions.extend(complete_option(arg, cmd, current_dir));
216	                }
217	            }
218	        }
219	        ParseState::Opt((opt, count)) => {
220	            completions.extend(complete_arg_value(
221	                arg.to_value(),
222	                opt,
223	                current_dir,
224	                count.saturating_sub(1),
225	            ));
226	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
227	            if count > min && can_switch_to_other_arg(opt, arg) {
228	                // The option's required values are satisfied and this word
229	                // would be parsed as a new flag rather than another value, so
230	                // also complete it as a positional, flag, option or subcommand.
231	                completions.extend(complete_arg(
232	                    arg,
233	                    cmd,
234	                    current_dir,
235	                    pos_index,
236	                    is_escaped,
237	                    ParseState::ValueDone,
238	                    used_args,
239	                )?);
240	            }
241	        }
242	    }
243	    filter_unavailable_args(&mut completions, cmd, used_args);
244	    if completions.iter().any(|a| !a.is_hide_set()) {
245	        completions.retain(|a| !a.is_hide_set());
246	    }
247	    dedup_argument_candidates(&mut completions, arg.is_empty());
248	
249	    let mut tags = Vec::new();
250	    for candidate in &completions {
251	        let tag = candidate.get_tag().cloned();
252	        if !tags.contains(&tag) {
253	            tags.push(tag);
254	        }
255	    }
256	    completions.sort_by_key(|c| {
257	        (
258	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
259	            c.get_display_order(),
260	        )
261	    });
262	
263	    Ok(completions)
264	}
265	
266	fn complete_option(
267	    arg: &clap_lex::ParsedArg<'_>,
268	    cmd: &clap::Command,
269	    current_dir: Option<&std::path::Path>,
270	) -> Vec<CompletionCandidate> {
271	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
272	    let mut completions = Vec::<CompletionCandidate>::new();
273	    if arg.is_empty() {
274	        completions.extend(longs_and_visible_aliases(cmd));
275	        completions.extend(hidden_longs_aliases(cmd));
276	
277	        let dash_or_arg = if arg.is_empty() {
278	            "-".into()
279	        } else {
280	            arg.to_value_os().to_string_lossy()
281	        };
282	        completions.extend(
283	            shorts_and_visible_aliases(cmd)
284	                .into_iter()
285	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
286	        );
287	    } else if arg.is_stdio() {
288	        // HACK: Assuming knowledge of is_stdio
289	        let dash_or_arg = if arg.is_empty() {
290	            "-".into()
291	        } else {
292	            arg.to_value_os().to_string_lossy()
293	        };
294	        completions.extend(
295	            shorts_and_visible_aliases(cmd)
296	                .into_iter()
297	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
298	        );
299	
300	        completions.extend(longs_and_visible_aliases(cmd));
301	        completions.extend(hidden_longs_aliases(cmd));
302	    } else if arg.is_escape() {
303	        // HACK: Assuming knowledge of is_escape
304	        completions.extend(longs_and_visible_aliases(cmd));
305	        completions.extend(hidden_longs_aliases(cmd));
306	    } else if let Some((flag, value)) = arg.to_long() {
307	        if let Ok(flag) = flag {
308	            if let Some(value) = value {
309	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
310	                    completions.extend(
311	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
312	                            .into_iter()
313	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
314	                    );
315	                }
316	            } else {
317	                completions.extend(
318	                    longs_and_visible_aliases(cmd)
319	                        .into_iter()
320	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
321	                );
322	                completions.extend(
323	                    hidden_longs_aliases(cmd)
324	                        .into_iter()
325	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
326	                );
327	            }
328	        }
329	    } else if let Some(short) = arg.to_short() {
330	        if !short.is_negative_number() {
331	            // Find the first takes_values option.
332	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
333	
334	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
335	            if let Some(opt) = takes_value_opt {
336	                let mut peek_short = short.clone();
337	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
338	                    short.next_flag();
339	                    true
340	                } else {
341	                    false
342	                };
343	
344	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
345	                completions.extend(
346	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
347	                        .into_iter()
348	                        .map(|comp| {
349	                            let sep = if has_equal { "=" } else { "" };
350	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
351	                        }),
352	                );
353	            } else {
354	                completions.extend(
355	                    shorts_and_visible_aliases(cmd)
356	                        .into_iter()
357	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
358	                );
359	            }
360	        }
361	    }
362	    debug!("complete_option: completions={completions:?}");
363	    completions
364	}
365	
366	fn complete_arg_value(
367	    value: Result<&str, &OsStr>,
368	    arg: &clap::Arg,
369	    current_dir: Option<&std::path::Path>,
370	    arg_index: usize,
371	) -> Vec<CompletionCandidate> {
372	    let mut values = Vec::new();
373	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
374	
375	    let (prefix, value) =
376	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
377	
378	    let value_os = match value {
379	        Ok(value) => OsStr::new(value),
380	        Err(value_os) => value_os,
381	    };
382	
383	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
384	        values.extend(completer.complete_at(arg_index, value_os));
385	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
386	        values.extend(complete_value_candidates(
387	            value_os,
388	            completer.value_candidates(),
389	        ));
390	    } else if let Some(possible_values) = possible_values(arg) {
391	        if let Ok(value) = value {
392	            values.extend(complete_candidates_str(
393	                value,
394	                possible_value_candidates(possible_values),
395	            ));
396	        }
397	    } else {
398	        match arg.get_value_hint() {
399	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
400	                // Should not complete
401	            }
402	            clap::ValueHint::AnyPath => {
403	                values.extend(complete_path(value_os, current_dir, &|_| true));
404	            }
405	            clap::ValueHint::FilePath => {
406	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
407	            }
408	            clap::ValueHint::DirPath => {
409	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
410	            }
411	            clap::ValueHint::ExecutablePath => {
412	                use is_executable::IsExecutable;
413	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
414	            }
415	            clap::ValueHint::CommandName
416	            | clap::ValueHint::CommandString
417	            | clap::ValueHint::CommandWithArguments
418	            | clap::ValueHint::Username
419	            | clap::ValueHint::Hostname
420	            | clap::ValueHint::Url
421	            | clap::ValueHint::EmailAddress => {
422	                // No completion implementation
423	            }
424	            _ => {
425	                // Safe-ish fallback
426	                values.extend(complete_path(value_os, current_dir, &|_| true));
427	            }
428	        }
429	
430	        values.sort();
431	    }
432	
433	    if let Some(prefix) = prefix {
434	        values = values
435	            .into_iter()
436	            .map(|comp| comp.add_prefix(prefix))
437	            .collect();
438	    }
439	    values = values
440	        .into_iter()
441	        .map(|comp| {
442	            if comp.get_tag().is_some() {
443	                comp
444	            } else {
445	                comp.tag(Some(arg.to_string().into()))
446	            }
447	        })
448	        .collect();
449	
450	    debug!("complete_arg_value: values={values:?}");
451	    values
452	}
453	
454	fn rsplit_delimiter<'s, 'o>(
455	    value: Result<&'s str, &'o OsStr>,
456	    delimiter: Option<char>,
457	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
458	    let delimiter = delimiter?;
459	    let value = value.ok()?;
460	    let pos = value.rfind(delimiter)?;
461	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
462	    Some((Some(prefix), Ok(value)))
463	}
464	
465	fn complete_value_candidates(
466	    value: &OsStr,
467	    completer: &dyn ValueCandidates,
468	) -> Vec<CompletionCandidate> {
469	    debug!("complete_value_candidates: value={value:?}");
470	
471	    let mut values = completer.candidates();
472	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
473	    values
474	}
475	
476	fn complete_candidates_str(
477	    value: &str,
478	    mut values: Vec<CompletionCandidate>,
479	) -> Vec<CompletionCandidate> {
480	    debug!("complete_candidates_str: value={value:?}");
481	
482	    values.retain(|comp| comp.get_value().starts_with(value));
483	    values
484	}
485	
486	fn complete_value_candidates_str(
487	    value: &str,
488	    completer: &dyn ValueCandidates,
489	) -> Vec<CompletionCandidate> {
490	    debug!("complete_value_candidates_str: value={value:?}");
491	
492	    complete_candidates_str(value, completer.candidates())
493	}
494	
495	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
496	    debug!(
497	        "complete_subcommand: cmd={:?}, value={:?}",
498	        cmd.get_name(),
499	        value
500	    );
501	
502	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
503	        .into_iter()
504	        .filter(|x| x.get_value().starts_with(value))
505	        .collect();
506	    if cmd.is_allow_external_subcommands_set() {
507	        let external_completer = cmd.get::<SubcommandCandidates>();
508	        if let Some(completer) = external_completer {
509	            scs.extend(complete_value_candidates_str(
510	                value,
511	                completer.value_candidates(),
512	            ));
513	        }
514	    }
515	
516	    scs.dedup();
517	    scs
518	}
