520	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
521	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
522	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
523	    debug!("longs: name={}", p.get_name());
524	
525	    p.get_arguments()
526	        .filter_map(|a| {
527	            a.get_long_and_visible_aliases().map(|longs| {
528	                longs
529	                    .into_iter()
530	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
531	            })
532	        })
533	        .flatten()
534	        .collect()
535	}
536	
537	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
538	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
539	    debug!("longs: name={}", p.get_name());
540	
541	    p.get_arguments()
542	        .filter_map(|a| {
543	            a.get_aliases().map(|longs| {
544	                longs.into_iter().map(|s| {
545	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
546	                })
547	            })
548	        })
549	        .flatten()
550	        .collect()
551	}
552	
553	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
554	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
555	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
556	    debug!("shorts: name={}", p.get_name());
557	
558	    p.get_arguments()
559	        .filter_map(|a| {
560	            a.get_short_and_visible_aliases().map(|shorts| {
561	                shorts.into_iter().map(|s| {
562	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
563	                        a.get_help()
564	                            .cloned()
565	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
566	                    )
567	                })
568	            })
569	        })
570	        .flatten()
571	        .collect()
572	}
573	
574	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
575	    candidate
576	        .help(arg.get_help().cloned())
577	        .id(Some(format!("arg::{}", arg.get_id())))
578	        .tag(Some(
579	            arg.get_help_heading()
580	                .unwrap_or("Options")
581	                .to_owned()
582	                .into(),
583	        ))
584	        .display_order(Some(arg.get_display_order()))
585	        .hide(arg.is_hide_set())
586	}
