599	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
600	///
601	/// Subcommand `rustup toolchain install` would be converted to
602	/// `("install", "rustup toolchain install")`.
603	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
604	    debug!("subcommands: name={}", p.get_name());
605	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
606	    p.get_subcommands()
607	        .flat_map(|sc| {
608	            sc.get_name_and_visible_aliases()
609	                .into_iter()
610	                .map(|s| populate_command_candidate(s, p, sc))
611	                .chain(
612	                    sc.get_aliases()
613	                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
614	                )
615	        })
616	        .collect()
617	}
618	
619	fn populate_command_candidate(
620	    candidate_name: &str,
621	    cmd: &clap::Command,
622	    subcommand: &clap::Command,
623	) -> CompletionCandidate {
624	    CompletionCandidate::new(candidate_name.to_owned())
625	        .help(subcommand.get_about().cloned())
626	        .id(Some(format!("command::{candidate_name}")))
627	        .tag(Some(
628	            cmd.get_subcommand_help_heading()
629	                .unwrap_or("Commands")
630	                .to_owned()
631	                .into(),
632	        ))
633	        .display_order(Some(subcommand.get_display_order()))
634	        .hide(subcommand.is_hide_set())
635	}
636	
637	/// Parse the short flags and find the first `takes_values` option.
638	///
639	/// Returns the raw leading flags, every matched argument, the first
640	/// `takes_values` option (if any), and the remaining unparsed flags.
641	fn parse_shortflags<'c, 's>(
642	    cmd: &'c clap::Command,
643	    mut short: clap_lex::ShortFlags<'s>,
644	) -> (
645	    String,
646	    Vec<&'c clap::Arg>,
647	    Option<&'c clap::Arg>,
648	    clap_lex::ShortFlags<'s>,
649	) {
650	    let takes_value_opt;
651	    let mut matched_opts = Vec::new();
652	    let mut leading_flags = String::new();
653	    // Find the first takes_values option.
654	    loop {
655	        match short.next_flag() {
656	            Some(Ok(opt)) => {
657	                leading_flags.push(opt);
658	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
659	                if let Some(opt) = opt {
660	                    matched_opts.push(opt);
661	                }
662	                if opt
663	                    .map(|o| o.get_num_args().expect("built").takes_values())
664	                    .unwrap_or(false)
665	                {
666	                    takes_value_opt = opt;
667	                    break;
668	                }
669	            }
670	            Some(Err(_)) | None => {
671	                takes_value_opt = None;
672	                break;
673	            }
674	        }
675	    }
676	
677	    (leading_flags, matched_opts, takes_value_opt, short)
678	}
679	
680	/// Whether the argument can be addressed by the long flag `flag`,
681	/// including visible and hidden aliases.
682	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
683	    arg.get_long() == Some(flag)
684	        || arg
685	            .get_all_aliases()
686	            .is_some_and(|aliases| aliases.contains(&flag))
687	}
688	
689	/// Whether the argument can be addressed by the short flag `flag`,
690	/// including visible and hidden aliases.
691	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
692	    arg.get_short() == Some(flag)
693	        || arg
694	            .get_all_short_aliases()
695	            .is_some_and(|aliases| aliases.contains(&flag))
696	}
697	
698	/// Remove argument candidates that are unavailable given the arguments
699	/// already present on the command line.
700	///
701	/// Two rules apply:
702	/// - Non-multiple argument groups: once any member of such a group is on the
703	///   command line, every member of that group (including the selected one and
704	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
705	/// - Explicit conflicts: a candidate that conflicts with an already-used
706	///   argument is removed; conflicts only need to be declared on one side.
707	///
708	/// Anything that is not an argument candidate (positional values,
709	/// subcommands, custom candidates) is left untouched.
710	fn filter_unavailable_args(
711	    completions: &mut Vec<CompletionCandidate>,
712	    cmd: &clap::Command,
713	    used_args: &[clap::Id],
714	) {
715	    if used_args.is_empty() {
716	        return;
717	    }
718	
719	    // Members of non-multiple groups that already have a member present.
720	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
721	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
722	        let members: Vec<&clap::Id> = group.get_args().collect();
723	        if members
724	            .iter()
725	            .any(|id| used_args.iter().any(|used| used == *id))
726	        {
727	            excluded_by_group.extend(members.into_iter().cloned());
728	        }
729	    }
730	
731	    completions.retain(|candidate| {
732	        let Some(arg) = candidate
733	            .get_id()
734	            .and_then(|id| id.strip_prefix("arg::"))
735	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
736	        else {
737	            return true;
738	        };
739	        if excluded_by_group.contains(arg.get_id()) {
740	            return false;
741	        }
742	        !used_args.iter().any(|used_id| {
743	            cmd.get_arguments()
744	                .find(|a| a.get_id() == used_id)
745	                .is_some_and(|used| args_conflict(cmd, arg, used))
746	        })
747	    });
748	}
749	
750	/// Record an argument seen on the command line, keeping the first occurrence
751	/// only so that repeating a flag neither alters filtering nor restores
752	/// candidates already excluded.
753	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
754	    if !used_args.iter().any(|used| used == id) {
755	        used_args.push(id.clone());
756	    }
757	}
758	
759	/// De-duplicate flag candidates.
760	///
761	/// With an empty word every long spelling of an argument (its long name and
762	/// visible aliases) is offered, while short spellings are still collapsed to
763	/// the canonical short and dropped for arguments that also have a long form.
764	/// Once a prefix is typed at most one spelling of an argument can match, so
765	/// candidates are de-duplicated by argument id as before.
766	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
767	    if empty_word {
768	        let long_ids: std::collections::HashSet<String> = completions
769	            .iter()
770	            .filter(|candidate| {
771	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
772	            })
773	            .filter_map(|candidate| candidate.get_id().cloned())
774	            .collect();
775	        let mut seen_short_ids = std::collections::HashSet::new();
776	        completions.retain(|candidate| {
777	            let Some(id) = candidate.get_id() else {
778	                return true;
779	            };
780	            if candidate.get_value().starts_with("--") {
781	                // Keep the long name and every visible alias.
782	                true
783	            } else if long_ids.contains(id) {
784	                // Prefer the long forms over the short ones.
785	                false
786	            } else {
787	                seen_short_ids.insert(id.clone())
788	            }
789	        });
790	    } else {
791	        let mut seen_ids = std::collections::HashSet::new();
792	        completions.retain(|candidate| {
793	            if let Some(id) = candidate.get_id().cloned() {
794	                seen_ids.insert(id)
795	            } else {
796	                true
797	            }
798	        });
799	    }
800	}
801	
802	/// Whether `first` and `second` conflict, no matter which one declares it.
803	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
804	    cmd.get_arg_conflicts_with(first)
805	        .iter()
806	        .any(|c| c.get_id() == second.get_id())
807	        || cmd
808	            .get_arg_conflicts_with(second)
809	            .iter()
810	            .any(|c| c.get_id() == first.get_id())
811	}
812	
813	/// Parse the positional arguments. Return the new state and the new positional index.
814	fn parse_positional<'a>(
815	    cmd: &clap::Command,
816	    pos_index: usize,
817	    is_escaped: bool,
818	    state: ParseState<'a>,
819	) -> (ParseState<'a>, usize) {
820	    let pos_arg = cmd
821	        .get_positionals()
822	        .find(|p| p.get_index() == Some(pos_index));
823	    let num_args = pos_arg
824	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
825	        .unwrap_or(1);
826	
827	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
828	        if num_args > 1 {
829	            (ParseState::Pos((pos_index, 1)), pos_index)
830	        } else {
831	            if is_escaped {
832	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
833	            } else {
834	                (ParseState::ValueDone, pos_index + 1)
835	            }
836	        }
837	    };
838	    match state {
839	        ParseState::ValueDone => {
840	            update_state_with_new_positional(pos_index)
841	        },
842	        ParseState::Pos((prev_pos_index, num_arg)) => {
843	            if prev_pos_index == pos_index {
844	                if num_arg + 1 < num_args {
845	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
846	                } else {
847	                    if is_escaped {
848	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
849	                    } else {
850	                        (ParseState::ValueDone, pos_index + 1)
851	                    }
852	                }
853	            } else {
854	                update_state_with_new_positional(pos_index)
855	            }
856	        }
857	        ParseState::Opt(..) => unreachable!(
858	            "This branch won't be hit,
859	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
860	        ),
861	    }
862	}
863	
864	/// Parse optional flag argument. Return new state
865	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
866	    let range = opt.get_num_args().expect("built");
867	    let max = range.max_values();
868	    if count < max {
869	        ParseState::Opt((opt, count + 1))
870	    } else {
871	        ParseState::ValueDone
872	    }
873	}
874	
875	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
876	/// for, honoring the value delimiter.
877	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
878	    match (opt.get_value_delimiter(), value.to_str()) {
879	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
880	        _ => 1,
881	    }
882	}
883	
884	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
885	    cmd.get_positionals()
886	        .find(|a| a.get_index() == Some(pos_index))
887	        .map(|p| p.is_allow_hyphen_values_set())
888	        .unwrap_or(false)
889	}
890	
891	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
892	    let val = arg.to_value_os();
893	    if val.starts_with("-") {
894	        if let ParseState::Opt((opt, _)) = state {
895	            return opt.is_allow_hyphen_values_set();
896	        }
897	    }
898	
899	    false
900	}
901	
902	/// Whether a word can terminate a still-open multi-value option and start a
903	/// new argument instead, the way the parser would read it.
904	///
905	/// While an option still owes values, the parser greedily consumes every plain
906	/// word as one of its values; only flag-like words can switch to another
907	/// argument. An option that accepts hyphen values consumes those too.
908	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
909	    if arg.is_escape() {
910	        // `--` cancels every pending option unless its values may start with `--`.
911	        return !pending.is_allow_hyphen_values_set();
912	    }
913	    if !arg.to_value_os().starts_with("-") {
914	        // A plain word is always another value of the pending option.
915	        return false;
916	    }
917	    if pending.is_allow_hyphen_values_set() {
918	        return false;
919	    }
920	    // `-` is a stdio/value, not a flag.
921	    if arg.is_stdio() {
922	        return false;
923	    }
924	    // Both long and short flag styles can start a new argument; unknown flags
925	    // still switch (and error during parsing) rather than become option values.
926	    arg.to_long().is_some() || arg.to_short().is_some()
927	}
